#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>
int main(int argc, char *argv[])
{
    char *end = NULL;
    long value;
    if (argc != 2) { fprintf(stderr, "Usage: %s <count>\n", argc > 0 ? argv[0] : "program"); return EXIT_FAILURE; }
    errno = 0;
    value = strtol(argv[1], &end, 10);
    if (end == argv[1] || *end != '\0' || errno == ERANGE || value < 1 || value > INT_MAX) {
        fputs("count must be from 1 through INT_MAX\n", stderr); return EXIT_FAILURE;
    }
    printf("validated count=%ld\n", value);
    return EXIT_SUCCESS;
}
